import numpy as np


class HardwareModelCoDesigner:
    """Co-design hardware accelerators and neural architectures together."""

    def __init__(self):
        self.hardware_configs = []
        self.model_configs = []

    def add_hardware_config(self, name, sram_kb, mac_units, clock_mhz, bandwidth_gbps, power_budget_w):
        self.hardware_configs.append({
            'name': name, 'sram_kb': sram_kb, 'mac_units': mac_units,
            'clock_mhz': clock_mhz, 'bandwidth_gbps': bandwidth_gbps,
            'power_budget_w': power_budget_w
        })

    def add_model_config(self, name, n_params, n_layers, activation_memory_mb):
        self.model_configs.append({
            'name': name, 'n_params': n_params,
            'n_layers': n_layers, 'activation_memory_mb': activation_memory_mb
        })

    def evaluate_pair(self, hw, model):
        total_ops = model['n_params'] * 2
        compute_cycles = total_ops / hw['mac_units']
        compute_latency = compute_cycles / (hw['clock_mhz'] * 1e6) * 1000

        total_memory_mb = model['n_params'] * 4 / 1e6 + model['activation_memory_mb']
        memory_latency = total_memory_mb / (hw['bandwidth_gbps'] / 8) * 1000

        total_latency = max(compute_latency, memory_latency)

        energy_per_mac = 0.2e-12
        compute_energy = total_ops * energy_per_mac

        dram_access_mb = model['n_params'] * 4 / 1e6
        dram_energy = dram_access_mb * 100

        total_energy = compute_energy + dram_energy

        avg_power = total_energy / (total_latency / 1000) if total_latency > 0 else float('inf')
        within_power = avg_power <= hw['power_budget_w']

        sram_needed_mb = model['activation_memory_mb']
        sram_available_mb = hw['sram_kb'] / 1024
        sram_fit = sram_needed_mb <= sram_available_mb

        return {
            'latency_ms': total_latency,
            'energy_pj': total_energy,
            'avg_power_w': avg_power,
            'within_power': within_power,
            'sram_fit': sram_fit,
            'feasible': within_power and sram_fit
        }

    def exhaustive_search(self):
        results = []
        for hw in self.hardware_configs:
            for model in self.model_configs:
                metrics = self.evaluate_pair(hw, model)
                results.append({
                    'hardware': hw['name'],
                    'model': model['name'],
                    **metrics
                })
        return results

    def find_optimal_pair(self, objective='latency'):
        results = self.exhaustive_search()
        feasible = [r for r in results if r['feasible']]

        if not feasible:
            return None

        if objective == 'latency':
            return min(feasible, key=lambda x: x['latency_ms'])
        elif objective == 'energy':
            return min(feasible, key=lambda x: x['energy_pj'])
        elif objective == 'power':
            return min(feasible, key=lambda x: x['avg_power_w'])

    def compute_pareto_frontier(self, results):
        feasible = [r for r in results if r['feasible']]
        pareto = []

        for r in feasible:
            dominated = False
            for other in feasible:
                if (other['latency_ms'] <= r['latency_ms'] and
                    other['energy_pj'] <= r['energy_pj'] and
                    (other['latency_ms'] < r['latency_ms'] or other['energy_pj'] < r['energy_pj'])):
                    dominated = True
                    break
            if not dominated:
                pareto.append(r)

        return pareto

    def generate_report(self, optimal, pareto):
        report = {
            'optimal_pair': {
                'hardware': optimal['hardware'],
                'model': optimal['model'],
                'latency_ms': optimal['latency_ms'],
                'energy_pj': optimal['energy_pj']
            },
            'pareto_size': len(pareto),
            'pareto_points': [
                {'hw': p['hardware'], 'model': p['model'],
                 'latency': p['latency_ms'], 'energy': p['energy_pj']}
                for p in pareto
            ]
        }
        return report


if __name__ == "__main__":
    np.random.seed(42)
    designer = HardwareModelCoDesigner()

    designer.add_hardware_config('Edge_TPU', 512, 4096, 500, 25, 2.0)
    designer.add_hardware_config('Mobile_GPU', 2048, 256, 1000, 50, 5.0)
    designer.add_hardware_config('Cloud_Accelerator', 32768, 65536, 1200, 1200, 75.0)

    designer.add_model_config('TinyCNN', 1e5, 5, 0.5)
    designer.add_model_config('MobileNet', 4e6, 28, 4.0)
    designer.add_model_config('ResNet50', 25e6, 50, 16.0)
    designer.add_model_config('Transformer_S', 100e6, 12, 64.0)

    optimal = designer.find_optimal_pair(objective='latency')
    all_results = designer.exhaustive_search()
    pareto = designer.compute_pareto_frontier(all_results)

    print(f"Optimal for latency: {optimal['hardware']} + {optimal['model']}")
    print(f"  Latency: {optimal['latency_ms']:.2f} ms")
    print(f"  Energy: {optimal['energy_pj']/1e12:.2f} nJ")
    print(f"\nPareto frontier size: {len(pareto)}")
    for p in pareto:
        print(f"  {p['hardware']} + {p['model']}: {p['latency_ms']:.2f}ms, {p['energy_pj']/1e12:.2f}nJ")
